import 'dart:convert';

import '../../../../core/utils/json_utils.dart';

/// An exercise generated by the backend; listening includes questions and audio.
class AiExamPrompt {
  const AiExamPrompt({
    required this.id,
    required this.title,
    required this.content,
    this.audioUrl = '',
    this.questions = const [],
  });

  final int id;
  final String title;
  final String content;
  final String audioUrl;
  final List<AiListeningQuestion> questions;

  factory AiExamPrompt.fromJson(Map<String, dynamic> json) => AiExamPrompt(
    id: json.asInt('promptId'),
    title: json.asString('title'),
    content: json.asString('content'),
    audioUrl: json.asString('audioUrl'),
    questions: List.unmodifiable(
      json.asList('questions').map(AiListeningQuestion.fromJson),
    ),
  );
}

/// Type 1 is multiple choice; type 2 is a short text answer.
class AiListeningQuestion {
  const AiListeningQuestion({
    required this.id,
    required this.type,
    required this.content,
    this.options = const [],
  });
  final int id;
  final int type;
  final String content;
  final List<String> options;

  factory AiListeningQuestion.fromJson(Map<String, dynamic> json) =>
      AiListeningQuestion(
        id: json.asInt('questionId'),
        type: json.asInt('type'),
        content: json.asString('content'),
        options: List.unmodifiable(
          json.asList('options').map((o) => o.asString('content')),
        ),
      );
}

/// IELTS scores from submit endpoints or a stored AI/teacher review.
class AiExamScore {
  const AiExamScore({
    required this.overall,
    this.fluency,
    this.lexical,
    this.grammar,
    this.pronunciation,
    this.taskResponse,
    this.coherence,
    this.feedback,
    this.transcript = '',
    this.attemptId,
  });

  final double overall;
  final double? fluency,
      lexical,
      grammar,
      pronunciation,
      taskResponse,
      coherence;
  final Object? feedback;
  final String transcript;
  final int? attemptId;

  factory AiExamScore.fromJson(Map<String, dynamic> json) {
    double? number(String key, [String? storedKey]) {
      final value =
          json.pick(key) ?? (storedKey == null ? null : json.pick(storedKey));
      return value is num ? value.toDouble() : double.tryParse('$value');
    }

    return AiExamScore(
      overall: number('score', 'scoreOverall') ?? 0,
      fluency: number('fluency', 'scoreFluency'),
      lexical:
          number('lexicalResource', 'scoreLexical') ?? number('scoreLexial'),
      grammar: number('grammar', 'scoreGrammar'),
      pronunciation: number('pronunciation', 'scorePronunciation'),
      taskResponse: number('taskResponse', 'scoreTask'),
      coherence: number('coherence', 'scoreCoherence'),
      feedback: decodeFeedback(json.pick('feedback')),
      transcript: json.asString('transcript'),
      attemptId: json.asIntOrNull('attemptId'),
    );
  }
}

/// Feedback is an object on submit and a JSON-encoded string in history.
Object? decodeFeedback(Object? value) {
  if (value is String) {
    try {
      return jsonDecode(value);
    } on FormatException {
      return value;
    }
  }
  return value;
}

/// Server-calculated listening score, answer key and script.
class AiListeningResult {
  const AiListeningResult({
    required this.score,
    required this.total,
    this.script = '',
    this.results = const [],
  });
  final int score, total;
  final String script;
  final List<AiListeningAnswerResult> results;

  factory AiListeningResult.fromJson(Map<String, dynamic> json) =>
      AiListeningResult(
        score: json.asInt('score'),
        total: json.asInt('total'),
        script: json.asString('script'),
        results: List.unmodifiable(
          json.asList('results').map(AiListeningAnswerResult.fromJson),
        ),
      );
}

/// One graded listening answer; option content itself is the submitted value.
class AiListeningAnswerResult {
  const AiListeningAnswerResult({
    required this.id,
    required this.content,
    required this.userAnswer,
    required this.correctAnswer,
    required this.isCorrect,
  });
  final int id;
  final String content, userAnswer, correctAnswer;
  final bool isCorrect;

  factory AiListeningAnswerResult.fromJson(Map<String, dynamic> json) =>
      AiListeningAnswerResult(
        id: json.asInt('questionId'),
        content: json.asString('content'),
        userAnswer: json.asString('userAnswer'),
        correctAnswer: json.asString('correctAnswer'),
        isCorrect: json.asBool('isCorrect'),
      );
}

Map<String, dynamic> _map(Object? value) =>
    value is Map ? Map<String, dynamic>.from(value) : {};

/// A saved submission listed by the review endpoint.
class AiExamSubmission {
  const AiExamSubmission({
    required this.id,
    required this.reviewId,
    required this.title,
    required this.content,
    required this.score,
    this.createdAt,
    this.isTeacherReviewed = false,
  });
  final int id, reviewId;
  final String title, content;
  final double score;
  final DateTime? createdAt;
  final bool isTeacherReviewed;

  factory AiExamSubmission.fromJson(Map<String, dynamic> json) {
    final prompt = _map(json.pick('prompt'));
    return AiExamSubmission(
      id: json.asInt('submissionId'),
      reviewId: json.asInt('aireviewId'),
      title: prompt.asString('title'),
      content: prompt.asString('content'),
      score: json.asDouble('scoreOverall'),
      createdAt: json.asDate('createdAt'),
      isTeacherReviewed: json.asBool('isTeacherReviewed'),
    );
  }
}

/// Nested review contract, including optional teacher scores and feedback.
class AiExamReview {
  const AiExamReview({
    required this.title,
    required this.content,
    required this.answer,
    required this.ai,
    this.teacher,
  });
  final String title, content, answer;
  final AiExamScore ai;
  final AiExamScore? teacher;

  factory AiExamReview.fromJson(Map<String, dynamic> json) {
    final prompt = _map(json.pick('prompt'));
    final answer = _map(json.pick('answer'));
    final written = answer.asString('answerText');
    return AiExamReview(
      title: prompt.asString('title'),
      content: prompt.asString('content'),
      answer: written.trim().isNotEmpty
          ? written
          : answer.asString('transcript'),
      ai: AiExamScore.fromJson(_map(json.pick('aiReview'))),
      teacher: json.pick('teacherReview') is Map
          ? AiExamScore.fromJson(_map(json.pick('teacherReview')))
          : null,
    );
  }
}
